public IndexDiff Update(IReadOnlyList<ChunkRef> current, string sourcePath)
{
    ArgumentNullException.ThrowIfNull(current);
    var diff = new IndexDiff(sourcePath);
    var seen = new HashSet<string>(StringComparer.Ordinal);
    foreach (var chunk in current)
    {
        if (!seen.Add(chunk.TextHash))
        {
            diff.Duplicates.Add(chunk);
            continue;
        }
        if (_byHash.TryGetValue(chunk.TextHash, out var existing))
        {
            existing.Touch(chunk.StartOffset, chunk.EndOffset);
            diff.Unchanged.Add(existing);
        }
        else
        {
            _byHash[chunk.TextHash] = chunk;
            diff.Added.Add(chunk);
        }
    }
    foreach (var stale in _bySource[sourcePath].Where(c => !seen.Contains(c.TextHash)).ToList())
    {
        _byHash.Remove(stale.TextHash);
        diff.Removed.Add(stale);
    }
    return diff;
}

